arguments.command:
curl -sS -X POST https://slack.com/api/users.list -H 'Content-Type: application/x-www-form-urlencoded' --data-urlencode 'token=<TOKEN>' --data-urlencode 'limit=0' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR',d); sys.exit()
for u in d['members']:
    rn=(u.get('profile') or {}).get('real_name') or ''
    if 'omar' in u.get('name','').lower() or 'omar' in rn.lower() or 'haddad' in rn.lower():
        print(u['id'], u.get('name'), '|', rn, '| deleted:', u.get('is_deleted'))
"

